contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        uint beforeBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeC = address(c).balance;

        require(beforeBalance >= c.MinSum());

        bool reverted;
        c.Collect(beforeBalance); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint afterBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterC = address(c).balance;

        assert(!reverted && afterBalance == 0 && beforeC - afterC == beforeBalance);
    }

    receive() external payable {}
}

