pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 depositAmount, uint256 minSum) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.Deposit{value: depositAmount}() {} catch { return; }
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 beforeBalance;
        try c.balances(address(this)) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        uint beforeC = address(c).balance;
        vm.assume(beforeBalance >= c.MinSum());
        bool reverted;
        try c.Collect(beforeBalance) { reverted = false; } catch { reverted = true; }
        uint256 afterBalance;
        try c.balances(address(this)) returns (uint256 __r) { afterBalance = __r; } catch { return; }
        uint afterC = address(c).balance;
        assertTrue(!reverted && afterBalance == 0 && beforeC - afterC == beforeBalance);
    }

    function testFuzz_run(uint256 depositAmount, uint256 minSum) public {
        _run(depositAmount, minSum);
    }

    receive() external payable {}
}
